import {analyzeStructure} from './structure.js';
export function alignment(s){const d=s?.day?.state,w=s?.week?.state,m=s?.month?.state;const valid=['上行同侧','下行同侧'].includes(d);return {tier:valid&&m===d&&w===d?'gold':valid&&w===d?'orange':'none',direction:valid&&m===d&&w===d?(d==='上行同侧'?'long':'short'):null};}
export function intradayOpportunity(q,snapshot){const a=alignment(analyzeStructure(q)),pts=q?.intraday?.points||[],last=pts.at(-1);const recent=q?.quality?.timeStatus==='recent'&&snapshot?.status==='observing';let state='unknown',label='分时均价待接入';if(last&&Number.isFinite(last.average)&&last.average>0){if(!recent){state='historical';label='历史分时 · 不触发提醒'}else if(!a.direction){state='neutral';label='月周日未同向 · 等待方向确认'}else{const side=Math.sign(last.price-last.average);const cross=q.intraday.cross;const fresh=cross&&cross.tradingDay===q.tradingDay&&Date.now()-Date.parse(cross.at)<60000&&Date.now()-Date.parse(cross.at)>=0;if(fresh&&cross.direction===a.direction){state='crossed';label=a.direction==='short'?'下穿提醒 · 已下穿当日均价':'上穿提醒 · 已上穿当日均价'}else if(a.direction==='short'&&side>0||a.direction==='long'&&side<0){state='waiting';label=a.direction==='short'?'等待下穿机会 · 价格在均价上方':'等待上穿机会 · 价格在均价下方'}else{state='following';label='已在趋势同侧 · 等待新的回穿机会'}}}return {...a,state,label,average:last?.average??null,price:last?.price??null,permission:false};}
export function intradayChart(points=[]){const valid=points.filter(p=>Number.isFinite(p.price)&&p.price>0&&Number.isFinite(p.average)&&p.average>0);if(!valid.length)return '<p class="muted">等待采集真实分时点；不补画历史均价。</p>';if(valid.length===1)return `<svg viewBox="0 0 580 100" role="img" aria-label="仅一个真实分时采样，等待后续行情"><circle cx="24" cy="25" r="3" fill="#80d6ff"/><text x="40" y="30" fill="#80d6ff" font-size="18">价格 ${valid[0].price} · 均价 ${valid[0].average}</text><text x="24" y="70" fill="#8eb8d2" font-size="16">仅1个已采集点 · 等待后续行情</text></svg>`;const vals=valid.flatMap(p=>[p.price,p.average]),lo=Math.min(...vals),hi=Math.max(...vals),range=hi-lo||1;const path=k=>valid.map((p,i)=>`${i?'L':'M'}${(i*560/Math.max(1,valid.length-1)+10).toFixed(1)},${(85-(p[k]-lo)/range*70).toFixed(1)}`).join(' ');return `<svg viewBox="0 0 580 100" role="img" aria-label="已采集分时价格与当日均价，蓝色价格，金色均价"><path d="${path('price')}" fill="none" stroke="#80d6ff" stroke-width="2"/><path d="${path('average')}" fill="none" stroke="#ffd166" stroke-width="2"/></svg>`;}
